/**
 * Spesimen Tanda Tangan PNG Standar untuk Stempel Otomatis Berkas TTB
 * Format PNG murni (Base64 Data URL) agar langsung disematkan oleh pdf-lib tanpa dependensi canvas/sharp saat runtime.
 */

export const FIFI_SIGNATURE_PNG = "data:image/png;base64,";
export const IDHAM_SIGNATURE_PNG = "data:image/png;base64,";
export const DAVILA_SIGNATURE_PNG = "data:image/png;base64,";

export function getSignatureForUploader(identifier?: string | null): string | null {
  if (!identifier) return null;
  const clean = identifier.trim().toLowerCase();
  if (
    clean === 'fifi' ||
    clean === 'nurul.hafifah' ||
    clean.includes('hafifah') ||
    clean.includes('fifi')
  ) {
    return FIFI_SIGNATURE_PNG;
  }
  if (clean === 'idham.khalid' || clean.includes('idham')) {
    return IDHAM_SIGNATURE_PNG;
  }
  if (clean === 'davila.zalianti' || clean.includes('davila') || clean.includes('vila')) {
    return DAVILA_SIGNATURE_PNG;
  }
  return null;
}
